WITH cur AS (
  SELECT batch_id FROM edu_access.`01-control`.current_batches WHERE source_id = 'deped_personnel'
), bronze AS (
  SELECT b.* FROM edu_access.`02-bronze`.deped_personnel_raw AS b JOIN cur ON b.batch_id = cur.batch_id
), c AS (
  SELECT * FROM edu_access.`03-silver`.deped_personnel_clean_candidate
), q AS (
  SELECT * FROM edu_access.`03-silver`.deped_personnel_quarantine_candidate
